draw:
var nF = p.nfilm, nS = p.nsub;
var flipTop = nF > 1.0;
var flipBot = nS > nF;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

var yTop = H * 0.40, yBot = H * 0.68;
var x0 = W * 0.10, x1 = W * 0.92;

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(x0, yTop); ctx.lineTo(x1, yTop); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0, yBot); ctx.lineTo(x1, yBot); ctx.stroke();

ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
for (var s = 0; s < 26; s++) {
  var xs = x0 + (x1 - x0) * s / 25;
  ctx.beginPath(); ctx.moveTo(xs, yBot); ctx.lineTo(xs + 7, yBot + 9); ctx.stroke();
}

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("air, n = 1.00", x0 + 4, yTop - 8);
ctx.fillText("film, n = " + nF.toFixed(2), x0 + 4, (yTop + yBot) / 2 + 4);
ctx.fillText("substrate, n = " + nS.toFixed(2), x0 + 4, yBot + 22);

var hitA = W * 0.34, hitB = W * 0.58;
var dx = (hitB - hitA);

ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.6;
ctx.beginPath(); ctx.moveTo(hitA - dx, yTop - (yTop - 12)); ctx.lineTo(hitA, yTop); ctx.stroke();
ctx.beginPath(); ctx.moveTo(hitA, yTop); ctx.lineTo(hitA + dx * 0.55, 12); ctx.stroke();

ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.6;
ctx.beginPath();
ctx.moveTo(hitA, yTop); ctx.lineTo(hitB, yBot); ctx.lineTo(hitB + (hitB - hitA), yTop);
ctx.lineTo(hitB + (hitB - hitA) + dx * 0.55, 12);
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("ray 1", hitA + dx * 0.30, 26);
ctx.fillText("ray 2", hitB + (hitB - hitA) + dx * 0.34, 26);
ctx.textAlign = "left";
ctx.fillText("in", Math.max(2, hitA - dx + 4), 26);

ctx.fillStyle = C.accent;
ctx.textAlign = "center";
ctx.fillText("extra path 2t, optical path 2nt", (hitA + hitB) / 2 + 20, yBot + 22);

ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 3]);
ctx.beginPath(); ctx.moveTo(W * 0.05, yTop); ctx.lineTo(W * 0.05, yBot); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("t", W * 0.05 + 4, (yTop + yBot) / 2 + 4);

var mark = function (x, y, on) {
  ctx.fillStyle = on ? C.accent : C.faint;
  ctx.beginPath(); ctx.arc(x, y, 5, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = C.ink;
  ctx.textAlign = "center";
  ctx.fillText(on ? "flip" : "no flip", x, y - 10);
};
mark(hitA, yTop, flipTop);
mark(hitB, yBot, flipBot);

var n = (flipTop ? 1 : 0) + (flipBot ? 1 : 0);
var cond = (n % 2 === 1) ? "bright when 2nt = (m + 1/2) lambda" : "bright when 2nt = m lambda";
out.note = n + " flip(s): " + cond;
